//! Post-PSO DXIL storage for opted-in shaders. PSO builds hold a lease until
//! the host has finished using their bytecode, including library loads.

use std::sync::atomic::Ordering::Relaxed;
use std::sync::{Arc, Mutex};

use crate::ram_trim::{self, COUNTERS, TrimPolicy, TrimThresholds};

use super::{KEPT, SHADERS, Shader};

pub(super) struct Dxil {
    original_hash: blake3::Hash,
    state: Mutex<State>,
}

struct State {
    bytes: Option<Arc<Vec<u8>>>,
    builds: usize,
    made_pso: bool,
    last_build_ms: u64,
}

pub(super) enum PsoBytecode<'a> {
    Kept(&'a [u8]),
    Leased {
        bytes: Arc<Vec<u8>>,
        // Dropped after `bytes` so immediate eviction does not leave a lease alive.
        pin: BuildPin<'a>,
    },
}

impl AsRef<[u8]> for PsoBytecode<'_> {
    fn as_ref(&self) -> &[u8] {
        match self {
            Self::Kept(bytes) => bytes,
            Self::Leased { bytes, .. } => bytes.as_slice(),
        }
    }
}

impl PsoBytecode<'_> {
    /// Only a successful library load or PSO creation makes a shader eligible.
    pub(super) fn pipeline_created(&mut self) {
        if let Self::Leased { pin, .. } = self {
            pin.made_pso = true;
        }
    }
}

pub(super) struct BuildPin<'a> {
    shader: &'a Shader,
    dxil: &'a Dxil,
    made_pso: bool,
}

impl Drop for BuildPin<'_> {
    fn drop(&mut self) {
        let now = crate::host::now_ms();
        let idle = {
            let mut state = self.dxil.state.lock().unwrap_or_else(|e| e.into_inner());
            state.builds -= 1;
            state.made_pso |= self.made_pso;
            state.last_build_ms = state.last_build_ms.max(now);
            state.builds == 0 && state.made_pso
        };
        if idle && let Some(thresholds) = TrimPolicy::cached().thresholds() {
            self.dxil.trim_with(self.shader, thresholds, now);
        }
    }
}

impl Dxil {
    pub(super) fn new(bytes: Vec<u8>) -> Self {
        Self {
            original_hash: blake3::hash(&bytes),
            state: Mutex::new(State {
                bytes: Some(Arc::new(bytes)),
                builds: 0,
                made_pso: false,
                last_build_ms: 0,
            }),
        }
    }

    fn pin<'a>(&'a self, shader: &'a Shader) -> Option<PsoBytecode<'a>> {
        // The same shader may be shared by several pipeline workers. Coalesce
        // reloads under its lock; the sweep tries this lock without blocking.
        let mut state = self.state.lock().unwrap_or_else(|e| e.into_inner());
        let bytes = if let Some(bytes) = &state.bytes {
            Arc::clone(bytes)
        } else {
            let container = shader.container.bytes();
            let reloaded = match crate::shader_cache::host_shader(container.as_ref()) {
                Ok(shader) => shader.dxil,
                Err(error) => {
                    tracing::warn!(%error, hash = %shader.hash, "shader DXIL reload failed");
                    return None;
                }
            };
            // Keep the exact code whose bindings were retained. For example, a
            // stale cache entry regenerated by another translator may differ.
            if blake3::hash(&reloaded) != self.original_hash {
                tracing::warn!(hash = %shader.hash, "shader DXIL changed on reload; refusing inconsistent bytecode");
                return None;
            }
            KEPT[3].fetch_add(reloaded.len() as u64, Relaxed);
            COUNTERS.shader_dxil_reloaded_bytes.fetch_add(reloaded.len() as u64, Relaxed);
            let reloaded = Arc::new(reloaded);
            state.bytes = Some(Arc::clone(&reloaded));
            reloaded
        };
        state.builds += 1;
        Some(PsoBytecode::Leased {
            bytes,
            pin: BuildPin { shader, dxil: self, made_pso: false },
        })
    }

    pub(super) fn trim_with(&self, shader: &Shader, thresholds: &TrimThresholds, now: u64) {
        let Ok(mut state) = self.state.try_lock() else { return };
        if !state.made_pso || state.builds != 0 {
            return;
        }
        let idle = now.saturating_sub(state.last_build_ms);
        if (thresholds.critical_memory || idle >= thresholds.shader_dxil_idle_ms)
            && let Some(bytes) = state.bytes.take()
        {
            let len = bytes.len() as u64;
            drop(bytes);
            KEPT[3].fetch_sub(len, Relaxed);
            COUNTERS.shader_dxil_dropped_bytes.fetch_add(len, Relaxed);
        }
        if thresholds.critical_memory || idle >= thresholds.shader_container_idle_ms {
            shader.container.compress();
        }
    }
}

impl Shader {
    pub(super) fn pso_bytecode(&self) -> Option<PsoBytecode<'_>> {
        let translated = self.translated()?;
        match &translated.dxil {
            Some(dxil) => dxil.pin(self),
            None => Some(PsoBytecode::Kept(&translated.host.dxil)),
        }
    }

    fn has_trimmable_dxil(&self) -> bool {
        self.translated.get().and_then(Option::as_ref).is_some_and(|t| t.dxil.is_some())
    }
}

/// Lets cold DXIL go and packs cold guest containers, without holding the
/// global shader table lock while compressing. Unused shaders stay untouched.
pub(crate) fn trim_shaders_with(policy: &TrimPolicy, now: u64) {
    if !ram_trim::enabled() {
        return;
    }
    let Some(thresholds) = policy.thresholds() else { return };
    let shaders: Vec<_> = {
        let table = SHADERS.lock().unwrap_or_else(|e| e.into_inner());
        let Some(table) = table.as_ref() else { return };
        table.values().filter(|s| s.has_trimmable_dxil()).cloned().collect()
    };
    for shader in shaders {
        if let Some(Some(t)) = shader.translated.get()
            && let Some(dxil) = &t.dxil
        {
            dxil.trim_with(&shader, thresholds, now);
        }
    }
}

